package com.bank.jvm;

import java.util.logging.*;

// Prints the effective JVM flags so ops can verify production tuning.
public class FlagInspectorDemo {
    private static final Logger log = Logger.getLogger(FlagInspectorDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JvmTuning tuning = new JvmTuning();
        tuning.printHeapSettings();
        tuning.printGcSettings();
        tuning.printMetaspaceSettings();
        tuning.printSafetyFlags();
        log.info("Banking service launched with verified JVM tuning");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in JvmTuning.java in a real project ───
class JvmTuning {
    private static final Logger log = Logger.getLogger(JvmTuning.class.getName());

    private com.sun.management.HotSpotDiagnosticMXBean diag() {
        return java.lang.management.ManagementFactory.getPlatformMXBean(
                com.sun.management.HotSpotDiagnosticMXBean.class);
    }
    private String opt(String name) {
        try { return diag().getVMOption(name).getValue(); }
        catch (Exception e) { return "n/a"; }
    }

    // -Xms / -Xmx show up via Runtime as total/max memory.
    void printHeapSettings() {
        Runtime rt = Runtime.getRuntime();
        log.info(String.format("Heap: -Xms(initial total)=%dMB  -Xmx(max)=%dMB",
                rt.totalMemory() / (1024 * 1024), rt.maxMemory() / (1024 * 1024)));
    }

    void printGcSettings() {
        log.info("GC: UseG1GC=" + opt("UseG1GC")
                + "  UseZGC=" + opt("UseZGC")
                + "  UseParallelGC=" + opt("UseParallelGC"));
        log.info("GC: MaxGCPauseMillis=" + opt("MaxGCPauseMillis"));
    }

    void printMetaspaceSettings() {
        log.info("Metaspace: MetaspaceSize=" + opt("MetaspaceSize")
                + "  MaxMetaspaceSize=" + opt("MaxMetaspaceSize"));
        long used = java.lang.management.ManagementFactory.getMemoryMXBean()
                .getNonHeapMemoryUsage().getUsed() / (1024 * 1024);
        log.info("Metaspace: currently used (non-heap) = " + used + "MB");
    }

    void printSafetyFlags() {
        log.info("Safety: HeapDumpOnOutOfMemoryError=" + opt("HeapDumpOnOutOfMemoryError")
                + "  HeapDumpPath=" + opt("HeapDumpPath"));
    }
}
